using Planner.Core;
using Planner.Data;
using Activity=Planner.Core.Activity;
static class BoardTests
{
    static void Equal<T>(T a,T b){if(!EqualityComparer<T>.Default.Equals(a,b))throw new Exception($"expected {a}, got {b}");}
    static PlannerState State(){var s=new PlannerState();s.Tables.Add(new(){Id="t",Name="工作"});return s;}
    public static void Register(Action<string,Action> test)
    {
        test("continuous list includes distant saved dates without month paging",()=>{var s=State();s.Activities.Add(new(){TableId="t",StartAt=new(2020,1,1,9,0,0),EndAt=new(2020,1,1,10,0,0)});s.Activities.Add(new(){TableId="t",StartAt=new(2030,12,31,23,0,0),EndAt=new(2031,1,1,1,0,0)});var windows=ContinuousList.Windows(s,new(2026,10,29),["t"]);Equal(2,windows.Count);Equal(new DateOnly(2020,1,1),windows[0].From);Equal(new DateOnly(2031,1,2),windows[^1].Until);Equal(0,ContinuousList.Windows(s,new(2026,10,29),[]).Count);});
        test("continuous recurrence exceeds six months using engine-safe windows",()=>{var s=State();s.Activities.Add(new(){Id="r",TableId="t",Kind="WEEKLY",DurationMin=120});s.Rules.Add(new(){ActivityId="r",ValidFrom=new(2024,1,1),ValidUntil=new(2027,12,31),WeekMask=1,StartTime="23:00"});var windows=ContinuousList.Windows(s,new(2026,10,29),["t"]);Equal(true,windows.All(w=>w.Until.DayNumber-w.From.DayNumber<=360));var days=windows.SelectMany(w=>BoardProjection.Range(s,w.From,w.Until)).Where(d=>d.Entries.Count>0).ToList();Equal(true,days.Any(d=>d.Date.Year==2024));Equal(true,days.Any(d=>d.Date.Year==2027));Equal(days.Count,days.Select(d=>d.Date).Distinct().Count());});
        test("month grid October 2026 starts Monday September28 and ends Sunday November1",()=>{var days=BoardProjection.MonthDays(new(2026,10,15));Equal(35,days.Count);Equal(new DateOnly(2026,9,28),days[0]);Equal(new DateOnly(2026,11,1),days[^1]);});
        test("month grid handles four five and six row months including leap February",()=>{Equal(28,BoardProjection.MonthDays(new(2021,2,1)).Count);Equal(35,BoardProjection.MonthDays(new(2024,2,1)).Count);Equal(42,BoardProjection.MonthDays(new(2020,8,1)).Count);});
        test("month pieces split midnight without creating a second occurrence identity",()=>{var s=State();s.Activities.Add(new(){Id="overnight",TableId="t",Title="跨日",StartAt=new(2026,10,31,23,0,0),EndAt=new(2026,11,1,2,0,0),DurationMin=180});var days=BoardProjection.Range(s,new(2026,10,31),new(2026,11,2));Equal(2,days.Count);Equal("overnight:once",days[0].Entries.Single().Occurrence.Key);Equal("overnight:once",days[1].Entries.Single().Occurrence.Key);Equal("23:00—24:00",days[0].Entries.Single().TimeText);Equal(true,days[1].Entries.Single().ContinuesFromYesterday);});
        test("month includes moved-in weekly exception from outside original month",()=>{var s=State();s.Activities.Add(new(){Id="a",TableId="t",Title="周期",Kind="WEEKLY",DurationMin=60});s.Rules.Add(new(){ActivityId="a",ValidFrom=new(2026,1,1),StartTime="09:00",WeekMask=16});s.Exceptions.Add(new(){ActivityId="a",OriginDate=new(2026,1,2),StartAt=new(2026,10,15,14,0,0),EndAt=new(2026,10,15,15,0,0)});var day=BoardProjection.Range(s,new(2026,10,15),new(2026,10,16)).Single();Equal("a:2026-01-02",day.Entries.Single().Occurrence.Key);});
        test("month visibility filter can show inactive tables without changing conflict scope",()=>{var s=State();s.Tables[0].Enabled=false;s.Activities.Add(new(){TableId="t",Title="停用仍显示",StartAt=new(2026,10,27,9,0,0),EndAt=new(2026,10,27,10,0,0)});Equal(1,BoardProjection.Range(s,new(2026,10,27),new(2026,10,28),["t"]).Single().Entries.Count);Equal(0,BoardProjection.Range(s,new(2026,10,27),new(2026,10,28),[]).Single().Entries.Count);Equal(0,CalendarEngine.Expand(s,new(2026,10,27),new(2026,10,28)).Count);});
        test("month drag command preserves time duration recurrence identity and reminder",()=>{var s=State();var a=new Activity{Id="a",TableId="t",Kind="WEEKLY",Title="周期",DurationMin=120};s.Activities.Add(a);s.Rules.Add(new(){ActivityId="a",ValidFrom=new(2026,10,1),StartTime="09:00",WeekMask=31});s.Reminders.Add(new(){ActivityId="a",Enabled=true,LeadMin=20});var o=CalendarEngine.Expand(s,new(2026,10,27),new(2026,10,28)).Single();var cmd=BoardProjection.MoveToDay(s,o,new(2026,11,1));Equal(new DateOnly(2026,10,27),cmd.OriginDate);Equal(9,cmd.Activity.StartAt!.Value.Hour);Equal(120,cmd.Activity.DurationMin);Equal(true,cmd.ReminderEnabled);Equal(20,cmd.ReminderLeadMin);var n=ChangeService.Apply(s,[cmd],s.Revision);Equal("a:2026-10-27",CalendarEngine.Expand(n,new(2026,11,1),new(2026,11,2)).Single().Key);});
        test("month drag shifts a once flexible window with the date",()=>{var s=State();s.Activities.Add(new(){Id="a",TableId="t",Title="灵活",ConstraintType="FLEXIBLE",StartAt=new(2026,10,27,10,0,0),EndAt=new(2026,10,27,11,0,0),WindowStart=new(2026,10,27,9,0,0),WindowEnd=new(2026,10,27,12,0,0),DurationMin=60});var o=CalendarEngine.Expand(s,new(2026,10,27),new(2026,10,28)).Single();var cmd=BoardProjection.MoveToDay(s,o,new(2026,10,28));var n=ChangeService.Apply(s,[cmd],0);Equal(new DateTime(2026,10,28,9,0,0),n.Activities.Single().WindowStart);});
        test("board completion and view preferences survive reopening without changing calendar",()=>{var dir=Path.Combine(Path.GetTempPath(),"board-"+Guid.NewGuid());try{var store=new BoardPreferenceStore(dir);store.Save(new(){View="LIST",Completed=["a:2026-10-27"]});var read=new BoardPreferenceStore(dir).Load();Equal("LIST",read.View);Equal(true,read.Completed.Contains("a:2026-10-27"));}finally{File.Delete(Path.Combine(dir,"board.json"));if(Directory.Exists(dir))Directory.Delete(dir);}});
        test("invalid board preferences fall back to month rather than prevent launch",()=>{var dir=Path.Combine(Path.GetTempPath(),"board-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{File.WriteAllText(Path.Combine(dir,"board.json"),"invalid-json");Equal("MONTH",new BoardPreferenceStore(dir).Load().View);}finally{File.Delete(Path.Combine(dir,"board.json"));Directory.Delete(dir);}});
    }
}
